bool FindCutFromBinBuffer(T *cut_pos, int *minCostAxis, BinBuffer<T> *bins, const real3<T> &bmin, const real3<T> &bmax) {
    // Calculate the surface area of each bin
    T surfaceArea = 0;
    for (int i = 0; i < bins->size(); i++) {
        surfaceArea += bins->at(i).surfaceArea();
    }

    // Find the bin with the minimum cost
    int minCostIndex = 0;
    T minCost = surfaceArea;
    for (int i = 0; i < bins->size(); i++) {
        T cost = bins->at(i).surfaceArea() / surfaceArea;
        if (cost < minCost) {
            minCost = cost;
            minCostIndex = i;
        }
    }

    // Calculate the cut position
    *cut_pos = bins->at(minCostIndex).centroid();

    // Calculate the minimum cost axis
    *minCostAxis = minCostIndex;

    return true;
}
